40	  it('accepts a valid global insight', () => {
41	    expect(InsightSchema.safeParse(validInsight).success).toBe(true);
42	  });
43	
44	  it('accepts a valid project-scoped insight with project_slug', () => {
45	    expect(InsightSchema.safeParse(validProjectInsight).success).toBe(true);
46	  });
